export const SWITCHBOARD_PATCHBAY_124 = ROWS.map(
  ([category, difficulty, canonicalEntityKey, callers, orderedJacks, stem, ahaFactoid], idx) => {
    const perm = PERMS[idx % PERMS.length];
    // perm[k] says which slot in jacks[] gets orderedJacks[k]!
    const jacks = ['', '', '', ''];
    const correctMapping = [0, 0, 0];
    let decoyJackIdx = 0;
    for (let k = 0; k < 4; k++) {
      const targetSlot = perm[k];
      jacks[targetSlot] = orderedJacks[k];
      if (k < 3) {
        correctMapping[k] = targetSlot;
      } else {
        decoyJackIdx = targetSlot;
      }
    }

    return {
      canonicalEntityKey,
      category,
      difficulty,
      stem,
      choices: jacks,
      answerIdx: decoyJackIdx,
      ahaFactoid,
      isKlaxonMyth: false,
      primaryToy: 'TOY_09_SWITCHBOARD_PATCHBAY',
      patchbay: {
        callers,
        jacks,
        correctMapping,
      },
    };
  }
);
